using Microsoft.Extensions.Caching.Memory;

public sealed class PriceService(IMemoryCache cache, PricingClient pricing)
{
    public async Task<Price> GetAsync(int productId, CancellationToken ct)
    {
        // Not atomic: every concurrent miss calls the pricing API
        var price = await cache.GetOrCreateAsync($"price:{productId}", entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            return pricing.GetPriceAsync(productId, ct);
        });
        return price!;
    }
}

using Microsoft.Extensions.Caching.Hybrid;

public sealed class PriceService(HybridCache cache, PricingClient pricing)
{
    private static readonly HybridCacheEntryOptions Options = new()
    {
        Expiration = TimeSpan.FromMinutes(5),          // shared level
        LocalCacheExpiration = TimeSpan.FromMinutes(1) // this server's memory
    };

    // One factory call per key on this server, however many callers wait
    public ValueTask<Price> GetAsync(int productId, CancellationToken ct) =>
        cache.GetOrCreateAsync($"price:{productId}",
            async token => await pricing.GetPriceAsync(productId, token),
            Options, cancellationToken: ct);
}
